RateCalculator:

```php
declare(strict_types=1);

namespace App\Domain;

use function bcmul;

/**
 * The core of billing: computes the cost of an event from tokens,
 * the price table, and off-peak discount.
 *
 * Rounding rules:
 *  - all intermediate computations are exact decimal (bcmath, scale 16);
 *  - exactly one rounding: the event final cost to 6 decimal places, HALF_UP;
 *  - report totals are a sum of already-rounded event costs.
 */
final class RateCalculator
{
    /** Price unit "per 1 million tokens" applied in millions. */
    private const TOKENS_PER_UNIT = '1000000';

    /**
     * @param array<string, string> $rates rates by token kind (decimal strings)
     */
    public static function eventCost(
        TokenUsage $usage,
        PricingUnit $unit,
        array $rates,
        ?OffPeakWindow $offPeak,
        \DateTimeInterface $utcTimestamp,
    ): Money {
        $cost = self::baseCost($usage, $unit, $rates);

        if ($offPeak !== null && $offPeak->covers($utcTimestamp)) {
            $cost = $cost->times($offPeak->multiplier());
        }

        return $cost->roundHalfUp(Money::US_DECIMALS);
    }

    /** @param array<string,string> $rates */
    private static function baseCost(TokenUsage $usage, PricingUnit $unit, array $rates): Money
    {
        if ($unit === PricingUnit::PerMillionUnified) {
            return self::perUnit($usage->total(), $rates['any'], $usage? no, just the token count);
        }

        $cost = Money::zero();
        foreach ($usage->byKind() as $kind => $tokens) {
            if ($tokens > 0) {
                $cost = $cost->plus(self::perUnit($tokens, $rates[$kind]));
            }
        }
        return $cost;
    }

    /** cost = tokens * rate / 1 000 000 (exact decimal arithmetic). */
    private static function perUnit(int $tokens, string $rate): Money
    {
        return Money::fromDecimalString((string) $tokens)
            ->times($rate)
            ->dividedBy(self::TOKENS_PER_UNIT);
    }
}
