    per-kind rates + any: Types::DECIMAL, nullable, length 20, scale 6.
    public ?string $rateInput = null; ... $rateAny;

    createdAt/updatedAt.

    /** @return array<string,string> rates by token kind, matching this scheme */
    public function rates(): array
    {
        if ($this->unit === PricingUnit::PerMillionUnified) {
            return ['any' => (string) $this->rateAny];
        }
        return [
            'input' => (string) $this->rateInput,
            'output' => (string) $this->rateOutput,
            'cache_read' => (string) $this->rateCacheRead,
            'cache_write' => (string) $this->rateCacheWrite,
        ];
    }

    public function applyRates(PricingUnit $unit, array $rates): void
    {
        $this->unit = $unit;
        if ($unit === PricingUnit::PerMillionUnified) {
            $this->rateAny = $rates['any'];
            $this->rateInput = $this->rateOutput = $this->rateCacheRead = $this->rateCacheWrite = null;
        } else {
            $this->rateInput = $rates['input'];
            $this->rateOutput = $rates['output'];
            $this->rateCacheRead = $rates['cache_read'];
            $this->rateCacheWrite = $rates['cache_write'];
            $this->rateAny = null;
        }
        $this->updatedAt = new \DateTimeImmutable();
    }
}
