    private static function decimalString(mixed $raw, string $ctx): string
    {
        if (!is_string($raw)) throw new ImportException($ctx.': ожидалась десятичная строка');
        if (preg_match('/^\d+(\.\d+)?$/', $raw) !== 1) throw new ImportException($ctx.': недопустимое десятичное число: '.$raw);
        return $raw;
    }
