    /**
     * Binds a price to all unpriced events (including retries for previously unpriced).
     * @return array{rated:int, unrated:list<UsageEvent>}
     */
    public function rateAll(): array
    {
        return $this->em->wrapInTransaction(function () {
            $unrated = [];
            $rated = 0;
            foreach ($this->events->findUnrated() as $event) {
                $model = $this->models->findByProviderCodeAndCode($event->provider, $event->model);
                $row = $model === null ? null : $this->priceRows->latestValidAt($model, $event->ts);
                if ($row === null) { $unrated[] = $event; continue; }
                $provider = $this->providers->findByCode($event->provider); // off-peak belongs to the provider
                $offPeak = $provider?->offPeak();
                $usage = new TokenUsage($event->tokensInput, $event->tokensOutput, $event->tokensCacheRead, $event->tokensCacheWrite);
                $cost = RateCalculator::eventCost($usage, $row->unit, $row->rates(), $offPeak, $event->ts);
                $event->markRated($cost, $row, new \DateTimeImmutable());
                $rated++;
            }
            $this->em->flush();
            return ['rated' => $rated, 'unrated' => $unrated];
        });
    }
}
