public function testParseTimeOfDay(): void
{
    self::assertSame(0, OffPeakWindow::parseTimeOfDay('00:00', 'x'));
    self::assertSame(86_399, OffPeakWindow::parseTimeOfDay('23:59', 'x'));
    self::assertSame(16 * 3600 + 30 * 60, OffPeakWindow::parseTimeOfDay('16:30', 'x'));

    foreach (['24:00', '12', '16:60', 'ab:cd', '16-30', '16.30'] as $bad) {
        $this->expectException(\ValueError::class);
        try {
            OffPeakWindow::parseTimeOfDay($bad, 'field');
        } finally {
            $this->addWarning('bad time: ' . $bad);
        }
    }
}

